'use client'

import * as React from 'react'
import { DropdownMenu as DropdownPrimitive } from 'radix-ui'
import { cn } from '@/lib/utils'
import { KbdGroup } from '@/registry/satin/ui/kbd'
import { useSatinLabels } from '@/registry/satin/ui/labels'
import { trackPointerModality } from '@/registry/satin/ui/pointer-modality'

// Rings after a mouse press: see pointer-modality.tsx.
trackPointerModality()

/**
 * DropdownMenu, 1:1 with the uiKit `DropdownMenu` (654:19150) and `DropdownMenu/Item`
 * (653:19165) sets. A 255px popover surface (max 520), 4px padding, radius-xl,
 * border/subtle, the shadcn `sm` shadow. Items are at least 32px high, 12px in, 6px top and
 * bottom, radius-lg, with an 8px gap between a 16px leading icon (text/muted), the content and
 * a trailing check (status green) when selected. An optional `shortcut` shows its keys (Kbd sm)
 * before the check. Hover, keyboard highlight and selected fill
 * bg/selected.
 *
 * Groups: `DropdownMenuGroup`. Content: a 14px medium label (20px line). `stacked` puts the
 * description under it, 2px apart, at 13px / 18px in text/muted; `inline` puts it on the same
 * baseline 12px after the label, at 13px, truncated. Groups have a 24px header in 12px
 * text/subtle and are 4px apart with a 1px bg/muted rule between them. Items are 4px apart.
 *
 * Built on the Radix DropdownMenu: arrow keys, typeahead, Escape, focus return.
 *
 * Other props on DropdownMenu, `ref` included, go to the menu's panel (the Radix Content).
 */
/** The popover surface menus share: radius-xl, border/subtle, bg/popover, the shadcn `sm` shadow. */
/** @internal Shared by Satin's own components; not part of the public API and may change in any release. */
export const menuSurfaceClass = cn(
  'sa:rounded-xl sa:border sa:border-border-subtle sa:bg-bg-popover',
  'sa:[box-shadow:0_1px_3px_0_var(--sa-effect-shadow-sm),0_1px_2px_-1px_var(--sa-effect-shadow-sm)]',
)
/** A group of rows, with a 1px bg/muted rule under every group but the last. */
/** @internal Shared by Satin's own components; not part of the public API and may change in any release. */
export const menuGroupClass = 'sa:flex sa:flex-col sa:gap-1 sa:not-last:after:block sa:not-last:after:h-px sa:not-last:after:bg-bg-muted'
/** The 24px group header in 12px text/subtle. */
// text/muted: a group's name is read to find a row, so it needs 4.5:1 (subtle is 2.6:1).
export const menuGroupLabelClass = 'sa:flex sa:h-6 sa:items-center sa:px-3 sa:text-xs sa:leading-3 sa:tracking-normal sa:text-text-muted'

export interface DropdownMenuProps
  extends Omit<
    React.ComponentProps<typeof DropdownPrimitive.Content>,
    'children' | 'asChild' | 'side' | 'align' | 'sideOffset' | 'onFocusOutside'
  > {
  /** The element that opens the menu. Rendered with `asChild`, so pass a Button. */
  trigger: React.ReactNode
  /** `DropdownMenuItem`s, optionally inside `DropdownMenuGroup`s. */
  children: React.ReactNode
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** Modal menus block the rest of the page while open. */
  modal?: boolean
  side?: 'top' | 'right' | 'bottom' | 'left'
  align?: 'start' | 'center' | 'end'
  sideOffset?: number
  /** Portal target. Defaults to `document.body`. */
  container?: HTMLElement | null
  /** Accessible name for the menu, when the trigger's text doesn't say enough. */
  'aria-label'?: string
  /** Focus moved outside a non-modal menu; call `preventDefault()` to keep it open. */
  onFocusOutside?: (event: Event) => void
  className?: string
}

export function DropdownMenu({
  trigger,
  children,
  open,
  defaultOpen,
  onOpenChange,
  modal = true,
  side = 'bottom',
  align = 'start',
  sideOffset = 8,
  container,
  onFocusOutside,
  className,
  ...props
}: DropdownMenuProps) {
  return (
    <DropdownPrimitive.Root open={open} defaultOpen={defaultOpen} onOpenChange={onOpenChange} modal={modal}>
      <DropdownPrimitive.Trigger asChild>{trigger}</DropdownPrimitive.Trigger>
      <DropdownPrimitive.Portal container={container}>
        <DropdownPrimitive.Content
          collisionPadding={8}
          {...props}
          data-slot="dropdown-menu"
          side={side}
          align={align}
          sideOffset={sideOffset}
          onFocusOutside={onFocusOutside}
          className={cn(
            'sa:pointer-events-auto sa:z-50 sa:flex sa:w-[255px] sa:max-w-[520px] sa:flex-col sa:gap-1 sa:overflow-x-clip sa:overflow-y-auto sa:p-1',
            'sa:max-h-(--radix-dropdown-menu-content-available-height)',
            menuSurfaceClass,
            'sa:origin-(--radix-dropdown-menu-content-transform-origin) sa:outline-none',
            'sa:data-[state=open]:animate-[satin-enter_var(--sa-duration-base)_var(--sa-ease-out)]',
            className,
          )}
        >
          {children}
        </DropdownPrimitive.Content>
      </DropdownPrimitive.Portal>
    </DropdownPrimitive.Root>
  )
}

/* ------------------------------------------------------------------------------------------ */

export interface DropdownMenuGroupProps extends React.ComponentProps<typeof DropdownPrimitive.Group> {
  /** The 24px group header. */
  label?: React.ReactNode
}

/** A titled group of items (Figma `_dropdown/group`). Groups get a rule between them. */
export function DropdownMenuGroup({ label, children, className, ...props }: DropdownMenuGroupProps) {
  return (
    <DropdownPrimitive.Group
      data-slot="dropdown-group"
      // Figma's divider lives inside the group, 8px under the last item; the last group has none.
      className={cn(menuGroupClass, className)}
      {...props}
    >
      {label ? (
        <DropdownPrimitive.Label className={menuGroupLabelClass}>
          {label}
        </DropdownPrimitive.Label>
      ) : null}
      {children}
    </DropdownPrimitive.Group>
  )
}

/* ------------------------------------------------------------------------------------------ */

/**
 * The row skin every menu shares: Dropdown, Select, Combobox and the Command menu. The highlight
 * is bg/selected; a row reached with the keyboard also gets the focus ring inside its edge, since
 * the fill alone is too faint to find (1.2:1). Real focus (Radix menus) shows it through
 * :focus-visible; lists that keep focus in a field (Combobox, Command menu) set data-keyboard.
 */
/** @internal Shared by Satin's own components; not part of the public API and may change in any release. */
export const menuItemClass = cn(
  'sa:flex sa:min-h-menu-row sa:w-full sa:cursor-pointer sa:items-center sa:gap-2 sa:rounded-lg sa:px-3 sa:py-1.5 sa:text-start sa:outline-none sa:select-none',
  'sa:focus-visible:[box-shadow:inset_0_0_0_2px_var(--sa-action-focus-ring)] sa:data-[keyboard]:[box-shadow:inset_0_0_0_2px_var(--sa-action-focus-ring)]',
  'sa:transition-colors sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out)',
  'sa:data-[highlighted]:bg-bg-selected sa:data-[force=hover]:bg-bg-selected sa:data-[selected]:bg-bg-selected',
  'sa:data-[disabled]:pointer-events-none sa:data-[disabled]:opacity-50',
  'sa:[&_svg]:pointer-events-none sa:[&_svg]:shrink-0',
)

export interface MenuItemContentProps {
  label: React.ReactNode
  description?: React.ReactNode
  /** Leading icon. 16px by default; stacked two-line items may use 20px (`iconSize={20}`). */
  icon?: React.ReactNode
  iconSize?: 16 | 20
  /** Marks the current value: a trailing check. */
  selected?: boolean
  layout?: 'stacked' | 'inline'
  /** Keys that run the item, e.g. "⌘N", shown on the right (Figma's `showShortcut`). */
  shortcut?: string
  /** Wraps the label, e.g. in Radix Select's `ItemText`. */
  renderLabel?: (label: React.ReactNode) => React.ReactNode
}

/** What sits inside a menu row: icon, label and description, then shortcut and check. */
export function MenuItemContent({
  label,
  description,
  icon,
  iconSize = 16,
  selected = false,
  layout = 'stacked',
  shortcut,
  renderLabel = (l) => l,
}: MenuItemContentProps) {
  const labels = useSatinLabels()
  return (
    <>
      {icon ? (
        <span
          className={cn(
            'sa:grid sa:shrink-0 sa:place-items-center sa:text-text-muted',
            iconSize === 20 ? 'sa:size-5 sa:[&_svg]:size-5 sa:[&_svg]:[stroke-width:1.5]' : 'sa:size-4 sa:[&_svg]:size-4 sa:[&_svg]:[stroke-width:1.875]',
          )}
        >
          {icon}
        </span>
      ) : null}

      {layout === 'stacked' ? (
        <span className="sa:flex sa:min-w-0 sa:flex-1 sa:flex-col sa:justify-center sa:gap-0.5">
          <span className="sa:text-base sa:leading-5 sa:font-medium sa:text-text-default">{renderLabel(label)}</span>
          {description ? <span className="sa:text-sm sa:leading-[18px] sa:text-text-muted">{description}</span> : null}
        </span>
      ) : (
        <span className="sa:flex sa:min-w-0 sa:flex-1 sa:items-baseline sa:gap-3">
          <span className="sa:shrink-0 sa:text-base sa:leading-5 sa:font-medium sa:whitespace-nowrap sa:text-text-default">{renderLabel(label)}</span>
          {description ? (
            <span className="sa:min-w-0 sa:flex-1 sa:truncate sa:text-sm sa:text-text-muted">{description}</span>
          ) : null}
        </span>
      )}

      {shortcut && <KbdGroup keys={shortcut} aria-hidden />}
      {selected && <span className="sa:sr-only">({labels.selected})</span>}
      {selected && (
        <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden className="sa:text-status-green-fg">
          <path
            d="M3.33333 8.66667L6 11.3333L12.6667 4.66667"
            stroke="currentColor"
            strokeWidth="1.25"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </svg>
      )}
    </>
  )
}

export interface DropdownMenuItemProps
  extends Omit<React.ComponentProps<typeof DropdownPrimitive.Item>, 'children'>,
    Omit<MenuItemContentProps, 'label' | 'renderLabel'> {
  label: string
}

export function DropdownMenuItem({
  label,
  description,
  icon,
  iconSize = 16,
  selected = false,
  layout = 'stacked',
  shortcut,
  className,
  ...props
}: DropdownMenuItemProps) {
  return (
    <DropdownPrimitive.Item
      data-slot="dropdown-item"
      data-selected={selected || undefined}
      textValue={label}
      className={cn(menuItemClass, className)}
      {...props}
    >
      <MenuItemContent
        label={label}
        description={description}
        icon={icon}
        iconSize={iconSize}
        selected={selected}
        layout={layout}
        shortcut={shortcut}
      />
    </DropdownPrimitive.Item>
  )
}
